import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
const bg=Color(0xff080d13),panel=Color(0xff121c27),green=Color(0xff54f0a0),muted=Color(0xff9aabba);
void main()=>runApp(const FipxezApp());
class FipxezApp extends StatelessWidget{const FipxezApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'FIPXEZ CPM2',debugShowCheckedModeBanner:false,theme:ThemeData(brightness:Brightness.dark,scaffoldBackgroundColor:bg,colorScheme:ColorScheme.fromSeed(seedColor:green,brightness:Brightness.dark),useMaterial3:true),home:const RemotePage());}
class RemotePage extends StatefulWidget{const RemotePage({super.key});@override State<RemotePage> createState()=>_RemotePageState();}
class _RemotePageState extends State<RemotePage>{
 static const secure=FlutterSecureStorage(); final url=TextEditingController(text:'http://192.168.1.100:8765'),token=TextEditingController();
 Map<String,dynamic>? info;String status='Hubungkan HP dan PC ke Wi-Fi yang sama.';bool busy=false;
 @override void initState(){super.initState();load();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();url.text=p.getString('pc_url')??url.text;token.text=await secure.read(key:'cpm2_worker_token')??'';if(mounted)setState((){});}
 Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('pc_url',url.text.trim());if(token.text.trim().isNotEmpty)await secure.write(key:'cpm2_worker_token',value:token.text.trim());}
 Future<void> call(String path,{bool post=false})async{if(busy)return;final base=url.text.trim().replaceAll(RegExp(r'/+$'),'');final uri=Uri.tryParse(base+path);if(uri==null||!uri.hasAuthority||(uri.scheme!='http'&&uri.scheme!='https')){setState(()=>status='URL PC tidak valid.');return;}setState(()=>busy=true);try{await save();final h={'Authorization':'Bearer ${token.text.trim()}','Content-Type':'application/json'};final r=post?await http.post(uri,headers:h).timeout(const Duration(seconds:15)):await http.get(uri,headers:h).timeout(const Duration(seconds:15));final d=jsonDecode(r.body);if(r.statusCode<200||r.statusCode>=300)throw Exception(d is Map?d['error']??'HTTP ${r.statusCode}':'HTTP ${r.statusCode}');if(path=='/health'){setState(()=>status='Terhubung ke FIPXEZ Worker di PC.');}else if(path=='/save/inspect'){setState(()=>info=Map<String,dynamic>.from(d));setState(()=>status=d['found']==true?'Save CPM2 ditemukan.':'Save belum ditemukan.');}else{setState(()=>status='Backup berhasil: ${d['backup']}');}}catch(e){setState(()=>status='Gagal: ${e.toString().replaceFirst('Exception: ','')}');}finally{if(mounted)setState(()=>busy=false);}}
 InputDecoration deco(String s)=>InputDecoration(labelText:s,filled:true,fillColor:bg,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12)));
 Widget act(String s,IconData i,VoidCallback f)=>SizedBox(width:double.infinity,height:50,child:FilledButton.icon(onPressed:busy?null:f,icon:Icon(i),label:Text(s,style:const TextStyle(fontWeight:FontWeight.bold)),style:FilledButton.styleFrom(backgroundColor:green,foregroundColor:bg)));
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('FIPXEZ • CPM2 REMOTE',style:TextStyle(fontWeight:FontWeight.w900,letterSpacing:1)),backgroundColor:bg),body:ListView(padding:const EdgeInsets.all(16),children:[
 Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(16),border:Border.all(color:green.withValues(alpha:.25))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('STEAM PC CONTROLLER',style:TextStyle(color:green,fontWeight:FontWeight.w900)),const SizedBox(height:8),Text(status,style:const TextStyle(color:muted)),if(busy)const Padding(padding:EdgeInsets.only(top:12),child:LinearProgressIndicator(color:green))]),
 const SizedBox(height:16),TextField(controller:url,decoration:deco('URL PC • http://192.168.1.10:8765'),keyboardType:TextInputType.url),const SizedBox(height:10),TextField(controller:token,decoration:deco('Worker token'),autocorrect:false),const SizedBox(height:12),
 act('TEST KONEKSI',Icons.wifi_tethering,()=>call('/health')),const SizedBox(height:10),act('CEK SAVE CPM2',Icons.folder_search,()=>call('/save/inspect')),const SizedBox(height:10),act('BACKUP SAVE OFFLINE',Icons.backup,()=>call('/save/backup',post:true)),
 if(info!=null)Container(margin:const EdgeInsets.only(top:16),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(14)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('SAVE INSPECTION',style:TextStyle(color:green,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text('Ditemukan: ${info!['found']}'),if(info!['path']!=null)SelectableText('Path: ${info!['path']}',style:const TextStyle(color:muted,fontSize:11)),if(info!['size_bytes']!=null)Text('Ukuran: ${info!['size_bytes']} bytes'),if(info!['modified']!=null)Text('Diubah: ${info!['modified']}'),if(info!['sha256']!=null)SelectableText('SHA-256: ${info!['sha256']}',style:const TextStyle(color:muted,fontSize:10)),Text(info!['message']?.toString()??'',style:const TextStyle(color:muted,fontSize:11))])),
 const SizedBox(height:18),const Text('CATATAN',style:TextStyle(color:green,fontWeight:FontWeight.w900)),const SizedBox(height:6),const Text('Versi awal hanya memeriksa dan mencadangkan save lokal/offline. Saldo Green Dollar/Gold Dollar belum diubah karena format save perlu diperiksa pada salinan terlebih dahulu. Tidak ada edit saldo online, bypass anti-cheat, atau manipulasi server.',style:TextStyle(color:muted,fontSize:12,height:1.5))
 ]));
 @override void dispose(){url.dispose();token.dispose();super.dispose();}
}